/// Native replay implementations for memory bindings.
#[inline]
fn destack_memory_advise_advise_range_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    address: u64,
    length: u64,
    advice: MemoryAdvice,
) -> RuntimeResult<()> {
    let _ = (&address, &length, &advice);

    binding.trace().run_binding_without_context(
        MEMORY_ADVISE_ADVISE_RANGE,
        binding.replay_payload_for(MEMORY_ADVISE_ADVISE_RANGE)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_memory_advise(binding, address, length, advice)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_memory_advise(binding, address, length, advice)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = MemoryAdviseAdviseRangeReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    MemoryAdviseAdviseRangeReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

